import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as p}from"./chunks/framework.BUXTSoD9.js";const _=JSON.parse('{"title":"تطوير SaaS حديث لتوليد الصور بالذكاء الاصطناعي - مشروع عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/modern-landing-page/index.md","filePath":"ar-sa/stage-2/assignments/modern-landing-page/index.md"}'),h={name:"ar-sa/stage-2/assignments/modern-landing-page/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="تطوير-saas-حديث-لتوليد-الصور-بالذكاء-الاصطناعي-مشروع-عملي" tabindex="-1">تطوير SaaS حديث لتوليد الصور بالذكاء الاصطناعي - مشروع عملي <a class="header-anchor" href="#تطوير-saas-حديث-لتوليد-الصور-بالذكاء-الاصطناعي-مشروع-عملي" aria-label="Permalink to “تطوير SaaS حديث لتوليد الصور بالذكاء الاصطناعي - مشروع عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب منك هذا المشروع العملي العمل على أساس مستند متطلبات منتج (PRD) حقيقي، وبناء منتج SaaS لتوليد الصور بالذكاء الاصطناعي من الصفر مستوحى من تجربة Midjourney. ستمر بالعملية الكاملة من تحليل المتطلبات وتفكيك المشروع والتطوير التكراري إلى الاختبار الشامل والنشر.</p><p>هذا هو مشروع Stage 2 التطبيقي الشامل. في الفصول السابقة، تعلمت مهارات فردية مثل تصميم واجهات الويب وتطوير واجهات البرمجيات الخلفية وقواعد البيانات ودمج المدفوعات - هذا المشروع يتطلب منك ربطها جميعاً معاً وتسليم نموذج أولي لمنتج قابل للتشغيل.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات الويب واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">المكتبة الحديثة للمكونات</a>)</li><li>تصميم وتطوير واجهات البرمجيات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>دمج المدفوعات (<a href="./../../backend/stripe-payment/">نظام الدفع Stripe</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع العملي، ستتمكن من:</p><ol><li>قراءة وفهم PRD حقيقي واستخراج قائمة مهام التطوير منه</li><li>تفكيك الوحدات بناءً على PRD ووضع خطة تنفيذ تدريجية</li><li>استخدام AI للمساعدة في بناء الهيكل الأمامي وتطوير واجهات البرمجيات الخلفية</li><li>التحقق من كل وحدة والتحسين التكراري</li><li>إكمال الاختبار الشامل من طرف إلى طرف ونقل المشروع من &quot;قابل للتشغيل&quot; إلى &quot;جاهز للتسليم&quot;</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستبنيه هو منصة SaaS حديثة لتوليد الصور بالذكاء الاصطناعي، تتضمن ثلاثة أنظمة فرعية:</p><table tabindex="0"><thead><tr><th>النظام الفرعي</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>الموقع الرسمي</strong></td><td>تقديم المنتج، التسعير، الأسئلة الشائعة، تحويل التسجيل</td></tr><tr><td><strong>مساحة عمل المستخدم</strong></td><td>إدخال Prompt، توليد الصور، المعرض، الأرصدة، الباقات، التفاعل المجتمعي</td></tr><tr><td><strong>لوحة الإدارة</strong></td><td>إدارة المستخدمين، إدارة المهام، إدارة المدفوعات، مراجعة المحتوى، مؤشرات SaaS، مراقبة النظام</td></tr></tbody></table><p>يجب أن تدعم الواجهة الخلفية القدرات الأساسية التالية: مصادقة المستخدمين، مهام توليد الصور، تخزين كائنات OSS، الأرصدة ومدفوعات الباقات، التفاعل الاجتماعي للصور، مراقبة بيانات العمليات.</p><div class="tip custom-block"><p class="custom-block-title">مدخل PRD</p><p>مستند متطلبات هذا المشروع متاح على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',15)),o("div",c,[e(s,null,{default:p(()=>[e(l,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD واستخراج الصفحات والوحدات ونماذج البيانات والحدود"},{title:"بناء الهيكل",description:"استخدام AI لإنشاء ثلاثة هياكل أمامية (www / app / admin)"},{title:"التطوير التكراري",description:"إضافة الواجهات والصلاحيات والمدفوعات والمراقبة لكل وحدة"},{title:"الاختبار والنشر",description:"الاختبار الشامل من طرف إلى طرف والنشر والتحضير للعرض"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركز على الإجابة عن الأسئلة التالية:</p><ul><li>كم عدد نقاط الدخول في النظام؟ وما هي الصفحات التي يغطيها كل منها؟</li><li>ما هي الوظائف الأساسية لكل صفحة؟</li><li>ما هي الوحدات والجداول في قاعدة البيانات التي تتضمنها الواجهة الخلفية؟</li><li>ما هو نطاق MVP؟ ما الذي سيتم تنفيذه في الإصدار الأول وما الذي لن يتم؟</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ في كتابة الكود. سوء فهم المتطلبات هو السبب الأكثر شيوعاً لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><p>بناءً على وصف PRD، قم بترتيب البنية الشاملة للنظام:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;الموقع الرسمي&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;مساحة عمل المستخدم&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;لوحة الإدارة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;المصادقة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;مهمة توليد الصور&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;تخزين كائنات OSS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;قاعدة البيانات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;المدفوعات والباقات&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;مشاركة / إعجاب / تعليق / إعادة نشر&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;لوحة مؤشرات SaaS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;مراقبة API / DB / المزود&quot;]</span></span></code></pre></div><p>يُنصح برسم مخطط البنية بكلماتك الخاصة للتأكد من أن فهمك للنظام كامل.</p><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-إنشاء-الصفحات-الأمامية" tabindex="-1">2.1 إنشاء الصفحات الأمامية <a class="header-anchor" href="#_2-1-إنشاء-الصفحات-الأمامية" aria-label="Permalink to “2.1 إنشاء الصفحات الأمامية”">​</a></h3><p>استخدم AI لإنشاء الهيكل الأساسي والبيانات الوهمية لجميع الصفحات أولاً. الهدف من هذه الخطوة هو بناء هيكل المعلومات والمسارات، دون الحاجة إلى ربط واجهات حقيقية.</p><p>مرجع لموجه الأوامر:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بناءً على PRD الحالي، ساعدني في إنشاء هيكل أمامي لمنصة SaaS حديثة لتوليد الصور بالذكاء الاصطناعي.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. ثلاثة نقاط دخول: www و app و admin</span></span>
<span class="line"><span>2. الموقع الرسمي يتضمن: الصفحة الرئيسية، التسعير، الأسئلة الشائعة</span></span>
<span class="line"><span>3. app يتضمن: تسجيل الدخول، إنشاء حساب، مساحة عمل التوليد، المعرض، الباقات، الأرصدة، المجتمع، تفاصيل الأعمال، المركز الشخصي</span></span>
<span class="line"><span>4. admin يتضمن: الصفحة الرئيسية للوحة التحكم، إدارة المستخدمين، إدارة المهام، إدارة المحتوى، إدارة الباقات، طلبات الدفع، إعدادات العمليات، مؤشرات SaaS، مراقبة النظام</span></span>
<span class="line"><span>5. إنشاء هيكل الصفحات والبيانات الوهمية فقط، دون ربط واجهات حقيقية</span></span>
<span class="line"><span>6. النمط مستوحى من Midjourney، بسيط وحديث مع طابع منتجي</span></span></code></pre></div><h3 id="_2-2-التحقق-من-هيكل-الصفحات" tabindex="-1">2.2 التحقق من هيكل الصفحات <a class="header-anchor" href="#_2-2-التحقق-من-هيكل-الصفحات" aria-label="Permalink to “2.2 التحقق من هيكل الصفحات”">​</a></h3><p>بعد إنشاء الهيكل، تحقق من كل عنصر:</p><ul><li>[ ] هل مسارات نقاط الدخول الثلاثة مستقلة (<code>/</code> و <code>/app</code> و <code>/admin</code>)</li><li>[ ] هل عدد الصفحات يتوافق مع PRD</li><li>[ ] هل يمكن الوصول إلى كل صفحة والتنقل فيها بشكل طبيعي</li><li>[ ] هل تعرض البيانات الوهمية حالات واجهة المستخدم الأساسية (قوائم، حالة فارغة، نماذج، إلخ)</li></ul><h2 id="الجزء-الثالث-التطوير-التكراري" tabindex="-1">الجزء الثالث: التطوير التكراري <a class="header-anchor" href="#الجزء-الثالث-التطوير-التكراري" aria-label="Permalink to “الجزء الثالث: التطوير التكراري”">​</a></h2><h3 id="_3-1-التقدم-حسب-الوحدات" tabindex="-1">3.1 التقدم حسب الوحدات <a class="header-anchor" href="#_3-1-التقدم-حسب-الوحدات" aria-label="Permalink to “3.1 التقدم حسب الوحدات”">​</a></h3><p>على أساس الهيكل، أضف الوظائف حسب الوحدات بالترتيب التالي:</p><ol><li><strong>المصادقة</strong>: التسجيل، تسجيل الدخول، التمييز بين الأدوار</li><li><strong>قاعدة البيانات</strong>: إنشاء جداول البيانات، واجهات القراءة والكتابة</li><li><strong>الأعمال الأساسية</strong>: مهام توليد الصور، تخزين النتائج</li><li><strong>تخزين OSS</strong>: رفع الصور والوصول إليها</li><li><strong>المدفوعات</strong>: الباقات، الأرصدة، دمج Stripe</li><li><strong>التفاعل الاجتماعي</strong>: المشاركة، الإعجاب، التعليق</li><li><strong>لوحة الإدارة</strong>: إدارة المستخدمين، إدارة المهام، مراجعة المحتوى</li><li><strong>مراقبة البيانات</strong>: لوحة مؤشرات SaaS، مراقبة النظام</li></ol><p>بعد إكمال كل وحدة، استخدم الجدول التالي للفحص الذاتي:</p><table tabindex="0"><thead><tr><th>عنصر الفحص</th><th>طريقة التحقق</th></tr></thead><tbody><tr><td>توافق الصفحات</td><td>هل عدد الصفحات ونقاط الدخول والوظائف تتوافق مع PRD</td></tr><tr><td>صحة الواجهات</td><td>هل معلمات الطلب وبنية الإرجاع ومعالجة الحالات معقولة</td></tr><tr><td>عزل الصلاحيات</td><td>هل يتم عزل المستخدمين العاديين عن المسؤولين</td></tr><tr><td>توافق البيانات</td><td>هل قاعدة البيانات و OSS والمدفوعات والأرصدة متطابقة</td></tr><tr><td>قابلية العرض</td><td>هل يمكن عرض سلسلة أعمال كاملة للآخرين</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>إذا وجدت أن المحتوى الذي أنشأه AI قد حاد عن PRD، لا تقم بإلغاء الصفحة بأكملها وإعادة البدء، فقط اطلب منه تعديل الوحدة المحددة.</p></div><h3 id="_3-2-الأدوار-والمسؤوليات" tabindex="-1">3.2 الأدوار والمسؤوليات <a class="header-anchor" href="#_3-2-الأدوار-والمسؤوليات" aria-label="Permalink to “3.2 الأدوار والمسؤوليات”">​</a></h3><p>أثناء التطوير التكراري، ستحتاج إلى لعب ثلاثة أدوار في نفس الوقت:</p><ul><li><strong>مدير المنتج</strong>: تأكيد أن وظائف كل وحدة تتوافق مع PRD</li><li><strong>المسؤول التقني</strong>: تأكيد أن خطة التنفيذ معقولة</li><li><strong>مهندس الاختبار</strong>: تأكيد أن الوظائف تعمل بشكل صحيح</li></ul><h2 id="الجزء-الرابع-الاختبار-والنشر" tabindex="-1">الجزء الرابع: الاختبار والنشر <a class="header-anchor" href="#الجزء-الرابع-الاختبار-والنشر" aria-label="Permalink to “الجزء الرابع: الاختبار والنشر”">​</a></h2><h3 id="_4-1-اختبار-من-طرف-إلى-طرف" tabindex="-1">4.1 اختبار من طرف إلى طرف <a class="header-anchor" href="#_4-1-اختبار-من-طرف-إلى-طرف" aria-label="Permalink to “4.1 اختبار من طرف إلى طرف”">​</a></h3><p>التركيز في المرحلة الأخيرة ليس على إضافة صفحات جديدة، بل على تشغيل سلسلة الأعمال الكاملة. تحقق من السيناريوهات التالية على الأقل:</p><ul><li>تسجيل حساب ← شراء أرصدة ← توليد صورة ← عرض السجل ← التفاعل والمشاركة</li><li>تسجيل دخول المسؤول ← عرض بيانات المستخدمين ← عرض إحصائيات المهام ← عرض مراقبة النظام</li></ul><h3 id="_4-2-النشر" tabindex="-1">4.2 النشر <a class="header-anchor" href="#_4-2-النشر" aria-label="Permalink to “4.2 النشر”">​</a></h3><p>انشر المشروع في بيئة الإنترنت العامة، وتأكد من:</p><ul><li>اكتمال تكوين متغيرات البيئة</li><li>صحة عنوان رد الاتصال لتسجيل الدخول</li><li>صحة عنوان رد الاتصال للمدفوعات</li><li>عدم وجود loading أو حالة فارغة أو رسائل خطأ مفقودة في الصفحات</li></ul><p>مرجع لدروس النشر: <a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>.</p><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (يتضمن README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الرئيسية (الصفحة الرئيسية للموقع، مساحة عمل التوليد، المعرض، صفحة الباقات، الصفحة الرئيسية للوحة الإدارة)</li><li>[ ] فيديو عرض مدته 60 ثانية (يغطي التسجيل ← التوليد ← العرض ← إدارة لوحة التحكم)</li></ul><p>يجب أن يتضمن README على الأقل: مقدمة المشروع، شرح الصفحات الرئيسية، التقنيات المستخدمة، خطوات التشغيل المحلي، قائمة متغيرات البيئة.</p><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البُعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>توافق PRD</td><td>الصفحات والوظائف وهياكل البيانات تتوافق بشكل أساسي مع PRD</td><td>القدرة على شرح علاقة كل قرار تصميمي بـ PRD بوضوح</td></tr><tr><td>حلقة المنتج</td><td>التسجيل ← شراء الأرصدة ← توليد صورة ← عرض السجل ← التفاعل والمشاركة يعمل بشكل كامل</td><td>حالة المدفوعات ورصيد الأرصدة وعدد مرات التوليد متطابقة</td></tr><tr><td>قدرات لوحة الإدارة</td><td>يمكن عرض إدارة المستخدمين والمهام والمدفوعات والمحتوى</td><td>لوحة مؤشرات SaaS وصفحة مراقبة النظام كاملة وقابلة للاستخدام</td></tr><tr><td>اكتمال الهندسة</td><td>تم ربط سلسلة الواجهة الأمامية والخلفية وقاعدة البيانات و OSS والمدفوعات</td><td>توجد معالجة الأخطاء والحالات الفارغة وحالة التحميل</td></tr><tr><td>جودة التسليم</td><td>قابل للنشر والتشغيل</td><td>README واضح وهيكل فيديو العرض مكتمل</td></tr></tbody></table><h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/multi-product-ui/">تصميم الصفحات والأزرار بالرجوع إلى معايير تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/llm-skills-beautiful/">تحسين مظهر واجهتك باستخدام LLM و Skills</a></li><li><a href="./../../frontend/design-to-code/">من النموذج الأولي للتصميم إلى كود المشروع</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام المكتبة الحديثة للمكونات</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات بمساعدة النماذج اللغوية الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li><li><a href="./../../backend/stripe-payment/">كيفية دمج Stripe وأنظمة الدفع الأخرى</a></li></ul>`,43))])}const P=n(h,[["render",b]]);export{_ as __pageData,P as default};
